}

app/back-studio/creatFiles/ConflictDialo:
/*
path :           app/back-studio/creatFiles/ConflictDialog.tsx
projectId:       <à fournir>
type:            component
generic:         false

role:            Dialogue de résolution de conflit. Affiché quand la route /save renvoie
                 409 : une ou plusieurs destinations existent déjà. Propose 4 actions :
                 Annuler, Ignorer, Renommer (suffixe -2, -3), Écraser. Ne prend AUCUNE
                 décision par défaut — l'utilisateur doit choisir explicitement.

flow:            Reçoit conflicts (liste de chemins), busy, onCancel, onResolve(policy).
                 Modal centré, overlay noir translucide. Ne se ferme pas au clic
                 extérieur (action destructrice potentielle).
ecosystem:       Dev = [
                   "@/app/back-studio/CreatFiles/CreatFilesView.tsx",
                   "@/app/back-studio/CreatFiles/ConflictDialog.tsx",
                 ]
relatedFiles:    ["@/app/back-studio/CreatFiles/CreatFilesView.tsx"]
imports:         ["react", "lucide-react",
                  "props reçues : { conflicts: readonly string[]; busy?: boolean; onCancel: () => void; onResolve: (policy: \"skip\" | \"overwrite\" | \"rename\") => void; }"]
exports:         ["ConflictDialog", "ConflictDialogProps"]
useBy:           ["@/app/back-studio/CreatFiles/CreatFilesView.tsx"]

userStories:     ["*en tant que développeur je veux choisir quoi faire en cas de conflit"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

"use client";
// "use client" justifié : gestionnaires de clic + overlay.

import { useEffect } from "react";
import { AlertTriangle, Loader2 } from "lucide-react";

export type ConflictDialogProps = {
  readonly conflicts: readonly string[];
  readonly busy?: boolean;
  readonly onCancel: () => void;
  readonly onResolve: (policy: "skip" | "overwrite" | "rename") => void;
};

export function ConflictDialog({
  conflicts,
  busy = false,
  onCancel,
  onResolve,
}: ConflictDialogProps) {
  /* ESC → annule. Entrée → rien (action destructrice : jamais par défaut). */
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape" && !busy) onCancel();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [busy, onCancel]);

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="conflict-title"
      className="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4 backdrop-blur-sm"
    >
      <div className="flex w-full max-w-2xl flex-col gap-4 rounded-xl border border-border bg-card p-5 shadow-xl">
        <header className="flex items-start gap-3">
          <span className="grid size-9 shrink-0 place-items-center rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400">
            <AlertTriangle className="h-4 w-4" aria-hidden />
          </span>
          <div className="flex min-w-0 flex-col gap-1">
            <h2
              id="conflict-title"
              className="text-lg font-bold text-foreground"
            >
              {conflicts.length} fichier(s) déjà existant(s)
            </h2>
            <p className="text-xs text-muted-foreground">
              Aucune action par défaut. Choisis explicitement ce qui doit se
              passer pour éviter tout écrasement accidentel.
            </p>
          </div>
        </header>

        <ul className="max-h-60 overflow-auto rounded-md border border-border/60 bg-muted/30 p-2 font-mono text-[11px] leading-relaxed text-foreground/90">
          {conflicts.map((p) => (
            <li key={p} className="truncate">
              {p}
            </li>
          ))}
        </ul>

        <footer className="flex flex-wrap justify-end gap-2">
          <button
            type="button"
            onClick={onCancel}
            disabled={busy}
            className="rounded-lg border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground transition-colors hover:bg-muted disabled:opacity-50"
          >
            Annuler
          </button>

          <button
            type="button"
            onClick={() => onResolve("skip")}
            disabled={busy}
            className="rounded-lg border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground transition-colors hover:bg-muted disabled:opacity-50"
          >
            Ignorer les existants
          </button>

          <button
            type="button"
            onClick={() => onResolve("rename")}
            disabled={busy}
            className="rounded-lg border border-primary/40 bg-primary/10 px-3 py-1.5 text-xs font-medium text-primary transition-colors hover:bg-primary/20 disabled:opacity-50"
          >
            Renommer (-2, -3…)
          </button>

          <button
            type="button"
            onClick={() => onResolve("overwrite")}
            disabled={busy}
            className="inline-flex items-center gap-1.5 rounded-lg border border-destructive/40 bg-destructive/10 px-3 py-1.5 text-xs font-medium text-destructive transition-colors hover:bg-destructive/20 disabled:opacity-50"
          >
            {busy && <Loader2 className="h-3 w-3 animate-spin" aria-hidden />}
            Écraser
          </button>
        </footer>
      </div>
    </div>
  );
}

app/back-studio/creatFiles/CreatFilesVie:
/*
path :           app/back-studio/creatFiles/CreatFilesView.tsx
projectId:       <à fournir>
type:            component
generic:         false

role:            Vue client de CreatFiles. Gère une liste ordonnée d'entrées { path,
                 content }, permet d'ajouter, supprimer, réordonner (↑ ↓), éditer
                 chaque champ, tout vider, copier le JSON, et enregistrer sur disque.
                 Le path est OPTIONNEL : s'il est vide, il est déduit de l'en-tête
                 Helpdev du contenu (champ `path :`) et affiché en aperçu.
                 L'enregistrement est protégé par un contrôle de conflit serveur
                 (jamais d'écrasement par défaut).
                 Après une copie OU une sauvegarde réussie, la liste est
                 automatiquement réinitialisée à une entrée vide.

flow:            useState(entries) → toolbar (ajouter / tout vider / copier / enregistrer)
                 → liste de <EntryRow> contrôlées → <pre> de prévisualisation JSON
                 (avec chemins résolus). handleSave(onConflict?) appelle
                 POST /api/back-studio/creat-files/save.
                 Si 409 → ouvre <ConflictDialog>. Si 200 → toast avec résumé + clearAll().
                 Le CopyButton reçoit onCopied={clearAll}.

ecosystem:       Dev = [
                   "@/app/back-studio/creatFiles/page.tsx",
                   "@/app/back-studio/creatFiles/CreatFilesView.tsx",
                   "@/app/back-studio/creatFiles/ConflictDialog.tsx",
                 ]
relatedFiles:    ["@/app/back-studio/creatFiles/page.tsx",
                  "@/app/back-studio/creatFiles/ConflictDialog.tsx",
                  "@/app/api/back-studio/creat-files/save/route.ts",
                  "@/components/common/CopyButton.tsx"]
imports:         ["react", "lucide-react", "sonner",
                  "@/components/common/CopyButton",
                  "@/app/back-studio/creatFiles/ConflictDialog",
                  "props reçues : aucune (composant autonome)"]
exports:         ["CreatFilesView"]
useBy:           ["@/app/back-studio/creatFiles/page.tsx"]

userStories:     ["*en tant que développeur je veux composer et créer un tableau de fichiers",
                  "*en tant que développeur je veux que le path soit déduit du contenu"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

"use client";

import { useMemo, useState } from "react";
import {
  ArrowDown,
  ArrowUp,
  HardDriveDownload,
  ListChecks,
  Loader2,
  Plus,
  Sparkles,
  Trash2,
} from "lucide-react";
import { toast } from "sonner";

import { CopyButton } from "@/components/common/CopyButton";
import { ConflictDialog } from "./ConflictDialog";

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

type FileEntry = {
  readonly id: string;
  path: string;
  content: string;
};

type SaveSummary = {
  readonly created: number;
  readonly overwritten: number;
  readonly renamed: number;
  readonly skipped: number;
  readonly failed: number;
};

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function nextId(): string {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }
  return `f-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function makeEmptyEntry(): FileEntry {
  return { id: nextId(), path: "", content: "" };
}

/**
 * Miroir client de la logique serveur : extrait `path : …` du premier
 * bloc /* … *\/ du contenu. Utilisé pour l'aperçu et le compteur.
 */
function extractPathHint(content: string): string | null {
  const start = content.indexOf("/*");
  if (start === -1) return null;
  const end = content.indexOf("*/", start + 2);
  if (end === -1) return null;
  const block = content.slice(start + 2, end);

  for (const rawLine of block.split(/\r?\n/)) {
    const m = rawLine.match(/^\s*path\s*:\s*(.+)$/);
    if (m) {
      const v = m[1]!.trim();
      return v.length > 0 ? v : null;
    }
  }
  return null;
}

/** Chemin effectif d'une entrée (explicite ou déduit du header). */
function effectivePath(entry: FileEntry): string | null {
  const explicit = entry.path.trim();
  if (explicit.length > 0) return explicit;
  return extractPathHint(entry.content);
}

/** Vrai si l'entrée produira une écriture (path explicite OU déduit). */
function isResolvable(entry: FileEntry): boolean {
  return effectivePath(entry) !== null;
}

function summarize(summary: SaveSummary): string {
  const parts: string[] = [];
  if (summary.created) parts.push(`${summary.created} créé(s)`);
  if (summary.overwritten) parts.push(`${summary.overwritten} écrasé(s)`);
  if (summary.renamed) parts.push(`${summary.renamed} renommé(s)`);
  if (summary.skipped) parts.push(`${summary.skipped} ignoré(s)`);
  if (summary.failed) parts.push(`${summary.failed} échec(s)`);
  return parts.length > 0 ? parts.join(", ") : "Aucune écriture";
}

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function CreatFilesView() {
  const [entries, setEntries] = useState<FileEntry[]>(() => [makeEmptyEntry()]);
  const [saving, setSaving] = useState(false);
  const [conflicts, setConflicts] = useState<readonly string[] | null>(null);

  /* Entrées qui produiront une écriture (path résolu, explicite ou déduit). */
  const filled = useMemo(() => entries.filter(isResolvable), [entries]);

  /* Nombre d'entrées dont le path est déduit (pour le badge informatif). */
  const deducedCount = useMemo(
    () =>
      filled.filter((e) => e.path.trim().length === 0 && extractPathHint(e.content))
        .length,
    [filled],
  );

  const json = useMemo(
    () =>
      JSON.stringify(
        filled.map((e) => {
          const p = effectivePath(e) ?? "";
          return { path: p, content: e.content };
        }),
        null,
        2,
      ),
    [filled],
  );

  /* ---------- Actions liste ---------- */

  function updateEntry(id: string, patch: Partial<FileEntry>) {
    setEntries((prev) =>
      prev.map((e) => (e.id === id ? { ...e, ...patch } : e)),
    );
  }

  function addEntry() {
    setEntries((prev) => [...prev, makeEmptyEntry()]);
  }

  function removeEntry(id: string) {
    setEntries((prev) => {
      if (prev.length <= 1) return [makeEmptyEntry()];
      return prev.filter((e) => e.id !== id);
    });
  }

  function moveEntry(id: string, dir: -1 | 1) {
    setEntries((prev) => {
      const idx = prev.findIndex((e) => e.id === id);
      if (idx === -1) return prev;
      const target = idx + dir;
      if (target < 0 || target >= prev.length) return prev;
      const next = [...prev];
      [next[idx], next[target]] = [next[target], next[idx]];
      return next;
    });
  }

  function clearAll() {
    setEntries([makeEmptyEntry()]);
  }

  /* ---------- Enregistrement ---------- */

  async function handleSave(onConflict?: "skip" | "overwrite" | "rename") {
    if (filled.length === 0) {
      toast.error("Aucune entrée exploitable (path ou en-tête Helpdev requis).");
      return;
    }

    setSaving(true);
    try {
      const res = await fetch("/api/back-studio/creat-files/save", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          files: filled.map((e) => ({
            // On envoie le path explicite s'il existe, sinon le serveur déduit.
            path: e.path.trim(),
            content: e.content,
          })),
          ...(onConflict ? { onConflict } : {}),
        }),
      });

      if (res.status === 409) {
        const data = (await res.json()) as { conflicts?: string[] };
        setConflicts(data.conflicts ?? []);
        return;
      }

      const data = (await res.json()) as {
        saved?: boolean;
        summary?: SaveSummary;
        forbidden?: string[];
        error?: string;
        hint?: string;
      };

      if (!res.ok) {
        throw new Error(
          data.error
            ? `${data.error}${data.hint ? ` — ${data.hint}` : ""}`
            : "Écriture impossible.",
        );
      }

      const summary = data.summary;
      if (summary) {
        if (summary.failed > 0) {
          toast.warning(summarize(summary));
        } else {
          toast.success(summarize(summary));
        }
      } else {
        toast.success("Fichiers enregistrés.");
      }

      setConflicts(null);

      /* Réinitialise la liste uniquement si aucune écriture n'a échoué,
         pour ne pas perdre les entrées à réessayer. */
      if (!summary || summary.failed === 0) {
        clearAll();
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : String(err));
    } finally {
      setSaving(false);
    }
  }

  /* ---------- Rendu ---------- */

  const isEmpty = filled.length === 0;

  return (
    <div className="flex flex-col gap-4">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-2 rounded-xl border border-border bg-card p-3">
        <button
          type="button"
          onClick={addEntry}
          className="inline-flex items-center gap-1.5 rounded-lg border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground transition-colors hover:bg-muted"
        >
          <Plus className="h-3.5 w-3.5" aria-hidden />
          Ajouter un fichier
        </button>

        <button
          type="button"
          onClick={clearAll}
          disabled={
            entries.length === 1 &&
            entries[0]?.path === "" &&
            entries[0]?.content === ""
          }
          className="inline-flex items-center gap-1.5 rounded-lg border border-border bg-background px-3 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:cursor-not-allowed disabled:opacity-50"
        >
          <Trash2 className="h-3.5 w-3.5" aria-hidden />
          Tout vider
        </button>

        <span className="ml-auto flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
          <span>
            <span className="font-mono font-semibold text-foreground">
              {filled.length}
            </span>
            /{entries.length} fichier(s) exploitable(s)
          </span>

          {deducedCount > 0 && (
            <span className="inline-flex items-center gap-1 rounded-full border border-chart-1/30 bg-chart-1/10 px-2 py-0.5 text-[10px] font-medium text-chart-1">
              <Sparkles className="h-3 w-3" aria-hidden />
              {deducedCount} path déduit(s) du header
            </span>
          )}

          <CopyButton
            value={json}
            label="Copier le JSON"
            toastLabel={`${filled.length} fichier(s) copié(s) — champs vidés`}
            disabled={isEmpty}
            onCopied={clearAll}
          />

          <button
            type="button"
            onClick={() => handleSave()}
            disabled={saving || isEmpty}
            className="inline-flex items-center gap-1.5 rounded-md bg-chart-4/10 px-3 py-1.5 text-xs font-medium text-chart-4 transition-colors hover:bg-chart-4/20 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {saving ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden />
            ) : (
              <HardDriveDownload className="h-3.5 w-3.5" aria-hidden />
            )}
            Enregistrer sur disque
          </button>
        </span>
      </div>

      {/* Liste des entrées */}
      <div className="flex flex-col gap-3">
        {entries.map((entry, index) => (
          <EntryRow
            key={entry.id}
            entry={entry}
            index={index}
            total={entries.length}
            onUpdate={(patch) => updateEntry(entry.id, patch)}
            onRemove={() => removeEntry(entry.id)}
            onMoveUp={() => moveEntry(entry.id, -1)}
            onMoveDown={() => moveEntry(entry.id, 1)}
          />
        ))}
      </div>

      {/* Aperçu du JSON */}
      <section className="flex flex-col gap-2">
        <header className="flex items-center justify-between">
          <div className="inline-flex items-center gap-2 text-xs font-bold text-foreground">
            <ListChecks className="h-3.5 w-3.5 text-primary" aria-hidden />
            JSON résultant
          </div>
          <span className="font-mono text-[10px] text-muted-foreground">
            {json.length.toLocaleString()} caractères
          </span>
        </header>
        <div className="max-h-[400px] overflow-auto rounded-xl border border-border bg-muted/30 p-3">
          <pre className="whitespace-pre-wrap font-mono text-[11px] leading-relaxed text-foreground/90">
            {isEmpty ? "(aucune entrée exploitable)" : json}
          </pre>
        </div>
      </section>

      {/* Dialogue de conflit */}
      {conflicts !== null && (
        <ConflictDialog
          conflicts={conflicts}
          busy={saving}
          onCancel={() => setConflicts(null)}
          onResolve={(policy) => handleSave(policy)}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Ligne d'entrée                                                     */
/* ------------------------------------------------------------------ */

function EntryRow({
  entry,
  index,
  total,
  onUpdate,
  onRemove,
  onMoveUp,
  onMoveDown,
}: {
  entry: FileEntry;
  index: number;
  total: number;
  onUpdate: (patch: Partial<FileEntry>) => void;
  onRemove: () => void;
  onMoveUp: () => void;
  onMoveDown: () => void;
}) {
  const isFirst = index === 0;
  const isLast = index === total - 1;

  const explicit = entry.path.trim();
  const deduced = extractPathHint(entry.content);
  const effective = explicit || deduced || null;
  const isDeduced = explicit.length === 0 && deduced !== null;
  const isEmpty = effective === null;

  return (
    <section
      className={`overflow-hidden rounded-xl border bg-card transition-colors ${
        isEmpty
          ? "border-border/60"
          : isDeduced
            ? "border-chart-1/40"
            : "border-primary/30"
      }`}
    >
      <header className="flex flex-wrap items-center gap-2 border-b border-border bg-muted/30 px-3 py-2">
        <span className="rounded-full border border-border/60 bg-background px-2 py-0.5 font-mono text-[10px] font-semibold text-foreground">
          #{index + 1}
        </span>

        {isEmpty && (
          <span className="rounded-full border border-amber-500/30 bg-amber-500/10 px-2 py-0.5 text-[10px] font-medium text-amber-700 dark:text-amber-400">
            ni path ni en-tête Helpdev — ignoré
          </span>
        )}

        {isDeduced && (
          <span className="inline-flex items-center gap-1 rounded-full border border-chart-1/30 bg-chart-1/10 px-2 py-0.5 text-[10px] font-medium text-chart-1">
            <Sparkles className="h-2.5 w-2.5" aria-hidden />
            path déduit : {deduced}
          </span>
        )}

        <div className="ml-auto flex items-center gap-1">
          <button
            type="button"
            onClick={onMoveUp}
            disabled={isFirst}
            aria-label="Monter"
            className="inline-flex h-6 w-6 items-center justify-center rounded-md border border-border bg-background text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:cursor-not-allowed disabled:opacity-40"
          >
            <ArrowUp className="h-3 w-3" aria-hidden />
          </button>
          <button
            type="button"
            onClick={onMoveDown}
            disabled={isLast}
            aria-label="Descendre"
            className="inline-flex h-6 w-6 items-center justify-center rounded-md border border-border bg-background text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:cursor-not-allowed disabled:opacity-40"
          >
            <ArrowDown className="h-3 w-3" aria-hidden />
          </button>
          <button
            type="button"
