/*
path :           app/back-studio/saveApp/readAppFiles.ts
projectId:       <à fournir>
type:            helper
generic:         false

role:            Orchestrateur du scan : lit la configuration d'exclusion, parcourt le disque,
                 parse l'en-tête de chaque fichier découvert, retourne la liste complète des
                 AppFile + statistiques (ignorés, tronqué).
flow:            readAppFiles() → readExcludes() → walkApp() → Promise.all(files.map(parseFile))
                 → retourne { files, stats }. Aucune écriture disque.
ecosystem:       Dev = [
                   "@/app/back-studio/saveApp/page.tsx",
                   "@/app/back-studio/saveApp/excludes.ts",
                   "@/app/back-studio/saveApp/readAppFiles.ts",
                   "@/lib/dev/types.ts",
                   "@/lib/dev/header-parser.ts",
                   "@/lib/dev/fs-walker.ts",
                 ]
relatedFiles:    ["@/lib/dev/types.ts",
                  "@/lib/dev/fs-walker.ts",
                  "@/lib/dev/header-parser.ts",
                  "@/app/back-studio/saveApp/excludes.ts"]
imports:         ["server-only",
                  "@/app/back-studio/saveApp/excludes",
                  "@/lib/dev/fs-walker",
                  "@/lib/dev/header-parser",
                  "@/lib/dev/types"]
exports:         ["readAppFiles", "ReadAppFilesResult", "ReadAppFilesStats"]
useBy:           ["@/app/back-studio/saveApp/page.tsx"]

userStories:     ["*en tant que développeur je veux récupérer tous les fichiers de l'app"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

import "server-only";

import { readExcludes } from "./excludes";
import { walkApp } from "@/lib/dev/fs-walker";
import { parseFile } from "@/lib/dev/header-parser";
import type { AppFile, ExcludesConfig } from "@/lib/dev/types";

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export type ReadAppFilesStats = {
  readonly total: number;
  readonly withHeader: number;
  readonly withoutHeader: number;
  readonly skippedDirs: number;
  readonly skippedFiles: number;
  readonly truncated: boolean;
  readonly totalBytes: number;
};

export type ReadAppFilesResult = {
  readonly files: readonly AppFile[];
  readonly config: ExcludesConfig;
  readonly stats: ReadAppFilesStats;
};

/* ------------------------------------------------------------------ */
/*  Orchestration                                                      */
/* ------------------------------------------------------------------ */

export async function readAppFiles(): Promise<ReadAppFilesResult> {
  const config = await readExcludes();
  const walk = await walkApp(config);

  const files = await Promise.all(
    walk.files.map((f) => parseFile(f.absolutePath)),
  );

  const withHeader = files.filter((f) => f.hasHeader).length;
  const totalBytes = files.reduce((sum, f) => sum + f.size, 0);

  return {
    files,
    config,
    stats: {
      total: files.length,
      withHeader,
      withoutHeader: files.length - withHeader,
      skippedDirs: walk.skippedDirs.length,
      skippedFiles: walk.skippedFiles.length,
      truncated: walk.truncated,
      totalBytes,
    },
  };
}

app/back-studio/saveApp/SaveAppView.tsx:
/*
path :           app/back-studio/saveApp/SaveAppView.tsx
projectId:       <à fournir>
type:            component
generic:         false

role:            Vue client principale de SaveApp. Orchestre : arborescence, filtres, règles
                 de scan, sélection multiple, choix du format (MD / JSON), aperçu live
                 du document, copie et sauvegarde (via /preview et /save).
flow:            Reçoit files (AppFile[]) et config (ExcludesConfig). State : selected
                 (Set<string>, tout coché par défaut), expanded, activeTypes, activeTags,
                 format ("md" | "json"), basename. Le filename est calculé
                 (basename + "." + format). L'aperçu est délégué à <PreviewPanel>.
                 handleSave appelle /save → toast avec le nom réel retourné (anti-
                 écrasement côté serveur).
ecosystem:       Dev = [
                   "@/app/back-studio/saveApp/page.tsx",
                   "@/app/back-studio/saveApp/SaveAppView.tsx",
                   "@/app/back-studio/saveApp/TreeView.tsx",
                   "@/app/back-studio/saveApp/PreviewPanel.tsx",
                   "@/lib/dev/types.ts",
                   "@/lib/dev/buildTree.ts",
                 ]
relatedFiles:    ["@/lib/dev/types.ts",
                  "@/lib/dev/buildTree.ts",
                  "@/app/back-studio/saveApp/TreeView.tsx",
                  "@/app/back-studio/saveApp/FiltersPanel.tsx",
                  "@/app/back-studio/saveApp/ExcludesPanel.tsx",
                  "@/app/back-studio/saveApp/PreviewPanel.tsx",
                  "@/app/api/back-studio/save-app/preview/route.ts",
                  "@/app/api/back-studio/save-app/save/route.ts"]
imports:         ["react", "lucide-react", "sonner",
                  "@/lib/dev/types",
                  "@/lib/dev/buildTree",
                  "props reçues : { files: readonly AppFile[]; config: ExcludesConfig; }"]
exports:         ["SaveAppView", "SaveAppViewProps"]
useBy:           ["@/app/back-studio/saveApp/page.tsx"]

userStories:     ["*en tant que développeur je veux sélectionner et exporter des fichiers"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

"use client";
// "use client" justifié : useState, useMemo, fetch, clipboard, interactions.

import { useMemo, useState } from "react";
import {
  CheckSquare,
  ChevronDown,
  ChevronRight,
  FileJson,
  FileText,
  FolderTree,
  Loader2,
  Save,
  Square,
} from "lucide-react";
import { toast } from "sonner";

import type {
  AppFile,
  ExcludesConfig,
  TreeDir,
  TreeNode,
} from "@/lib/dev/types";
import { buildTree } from "@/lib/dev/buildTree";
import { TreeView } from "./TreeView";
import { FiltersPanel } from "./FiltersPanel";
import { ExcludesPanel } from "./ExcludesPanel";
import { PreviewPanel } from "./PreviewPanel";

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export type SaveAppViewProps = {
  readonly files: readonly AppFile[];
  readonly config: ExcludesConfig;
};

type Format = "md" | "json";

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

function collectDirPaths(nodes: readonly TreeNode[]): string[] {
  const out: string[] = [];
  for (const n of nodes) {
    if (n.kind === "dir") {
      out.push(n.path);
      out.push(...collectDirPaths(n.children));
    }
  }
  return out;
}

function collectFilesFromDir(dir: TreeDir): AppFile[] {
  const out: AppFile[] = [];
  for (const child of dir.children) {
    if (child.kind === "file") out.push(child.file);
    else out.push(...collectFilesFromDir(child));
  }
  return out;
}

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function SaveAppView({ files, config }: SaveAppViewProps) {
  const [selected, setSelected] = useState<Set<string>>(
    () => new Set(files.map((f) => f.relativePath)),
  );

  const [expanded, setExpanded] = useState<Set<string>>(() => {
    const tree = buildTree(files);
    return new Set(collectDirPaths(tree));
  });

  const [activeTypes, setActiveTypes] = useState<Set<string>>(new Set());
  const [activeTags, setActiveTags] = useState<Set<string>>(new Set());

  const [format, setFormat] = useState<Format>("md");
  const [basename, setBasename] = useState(`save-${today()}`);
  const [saving, setSaving] = useState(false);

  /* Nom final = basename + extension du format courant. */
  const filename = `${basename}.${format}`;

  /* ---------- Valeurs dérivées ---------- */

  const availableTypes = useMemo(() => {
    const set = new Set<string>();
    for (const f of files) if (f.header.type) set.add(f.header.type);
    return Array.from(set).sort();
  }, [files]);

  const availableTags = useMemo(() => {
    const set = new Set<string>();
    for (const f of files) for (const t of f.header.tag) set.add(t);
    return Array.from(set).sort();
  }, [files]);

  const visibleFiles = useMemo(() => {
    const filterByType = activeTypes.size > 0;
    const filterByTag = activeTags.size > 0;

    return files.filter((f) => {
      if (filterByType) {
        if (!f.header.type || !activeTypes.has(f.header.type)) return false;
      }
      if (filterByTag) {
        const has = f.header.tag.some((t) => activeTags.has(t));
        if (!has) return false;
      }
      return true;
    });
  }, [files, activeTypes, activeTags]);

  const tree = useMemo(() => buildTree(visibleFiles), [visibleFiles]);

  const visiblePaths = useMemo(
    () => new Set(visibleFiles.map((f) => f.relativePath)),
    [visibleFiles],
  );

  const visibleSelectedCount = useMemo(() => {
    let n = 0;
    for (const p of visiblePaths) if (selected.has(p)) n++;
    return n;
  }, [visiblePaths, selected]);

  const selectedFiles = useMemo(
    () => files.filter((f) => selected.has(f.relativePath)),
    [files, selected],
  );

  const selectedPaths = useMemo(
    () => selectedFiles.map((f) => f.relativePath),
    [selectedFiles],
  );

  const totalBytes = useMemo(
    () => selectedFiles.reduce((sum, f) => sum + f.size, 0),
    [selectedFiles],
  );

  const overSizeLimit = totalBytes > config.maxBytes;

  const allVisibleSelected =
    visibleFiles.length > 0 && visibleSelectedCount === visibleFiles.length;

  /* ---------- Actions sélection ---------- */

  function toggleFile(path: string) {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  }

  function toggleDir(dir: TreeDir) {
    const dirFiles = collectFilesFromDir(dir);
    const allSelected = dirFiles.every((f) => selected.has(f.relativePath));
    setSelected((prev) => {
      const next = new Set(prev);
      for (const f of dirFiles) {
        if (allSelected) next.delete(f.relativePath);
        else next.add(f.relativePath);
      }
      return next;
    });
  }

  function toggleExpand(path: string) {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  }

  function toggleSelectAllVisible() {
    setSelected((prev) => {
      const next = new Set(prev);
      if (allVisibleSelected) {
        for (const p of visiblePaths) next.delete(p);
      } else {
        for (const p of visiblePaths) next.add(p);
      }
      return next;
    });
  }

  function expandAll() {
    const tree = buildTree(files);
    setExpanded(new Set(collectDirPaths(tree)));
  }

  function collapseAll() {
    setExpanded(new Set());
  }

  /* ---------- Actions filtres ---------- */

  function toggleType(type: string) {
    setActiveTypes((prev) => {
      const next = new Set(prev);
      if (next.has(type)) next.delete(type);
      else next.add(type);
      return next;
    });
  }

  function toggleTag(tag: string) {
    setActiveTags((prev) => {
      const next = new Set(prev);
      if (next.has(tag)) next.delete(tag);
      else next.add(tag);
      return next;
    });
  }

  function clearFilters() {
    setActiveTypes(new Set());
    setActiveTags(new Set());
  }

  /* ---------- Sauvegarde (fetch /save) ---------- */

  async function handleSave() {
    if (selectedFiles.length === 0) {
      toast.error("Aucun fichier sélectionné.");
      return;
    }
    if (overSizeLimit) {
      toast.error("Sélection trop volumineuse.");
      return;
    }

    setSaving(true);
    try {
      const res = await fetch("/api/back-studio/save-app/save", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          filename,
          paths: selectedPaths,
        }),
      });

      const data = (await res.json()) as {
        saved?: boolean;
        filename?: string;
        publicPath?: string;
        fileCount?: number;
        error?: string;
      };

      if (!res.ok || !data.publicPath) {
        throw new Error(data.error ?? "Erreur de sauvegarde.");
      }

      toast.success(
        `Sauvegardé : ${data.filename} (${data.fileCount ?? 0} fichier(s))`,
      );
    } catch (err) {
      toast.error(err instanceof Error ? err.message : String(err));
    } finally {
      setSaving(false);
    }
  }

  /* ---------- Rendu ---------- */

  return (
    <div className="grid gap-6 lg:grid-cols-[280px_1fr]">
      {/* Colonne gauche : règles + filtres */}
      <aside className="flex flex-col gap-4">
        <ExcludesPanel initialConfig={config} />
        <FiltersPanel
          availableTypes={availableTypes}
          availableTags={availableTags}
          activeTypes={activeTypes}
          activeTags={activeTags}
          onToggleType={toggleType}
          onToggleTag={toggleTag}
          onClearFilters={clearFilters}
        />
      </aside>

      {/* Colonne droite : arbre + toolbar + aperçu + actions */}
      <section className="flex min-w-0 flex-col gap-4">
        {/* Toolbar */}
        <div className="flex flex-wrap items-center gap-2 rounded-xl border border-border bg-card p-3">
          <button
            type="button"
            onClick={toggleSelectAllVisible}
            disabled={visibleFiles.length === 0}
            className="inline-flex items-center gap-1.5 rounded-lg border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground transition-colors hover:bg-muted disabled:cursor-not-allowed disabled:opacity-50"
          >
            {allVisibleSelected ? (
              <>
                <CheckSquare className="h-3.5 w-3.5" aria-hidden />
                Tout désélectionner
              </>
            ) : (
              <>
                <Square className="h-3.5 w-3.5" aria-hidden />
                Tout sélectionner
              </>
            )}
          </button>

          <button
            type="button"
            onClick={expandAll}
            className="inline-flex items-center gap-1 rounded-lg border border-border bg-background px-2 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted"
          >
            <ChevronDown className="h-3.5 w-3.5" aria-hidden />
            Tout ouvrir
          </button>

          <button
            type="button"
            onClick={collapseAll}
            className="inline-flex items-center gap-1 rounded-lg border border-border bg-background px-2 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted"
          >
            <ChevronRight className="h-3.5 w-3.5" aria-hidden />
            Tout fermer
          </button>

          <span className="ml-auto flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
            <span>
              <span className="font-mono font-semibold text-foreground">
                {visibleSelectedCount}
              </span>
              /{visibleFiles.length} visibles
            </span>
            <span>
              <span className="font-mono font-semibold text-foreground">
                {selectedFiles.length}
              </span>
              /{files.length} au total
            </span>
            <span
              className={
                overSizeLimit ? "text-rose-600 dark:text-rose-400" : ""
              }
            >
              {(totalBytes / 1024).toFixed(1)} Ko /{" "}
              {(config.maxBytes / 1_048_576).toFixed(0)} Mo
            </span>
          </span>
        </div>

        {/* Arbre */}
        <div className="max-h-[560px] overflow-auto rounded-xl border border-border bg-card p-3">
          {visibleFiles.length === 0 ? (
            <p className="p-6 text-center text-xs italic text-muted-foreground">
              Aucun fichier ne correspond aux filtres actifs.
            </p>
          ) : (
            <TreeView
              nodes={tree}
              selected={selected}
              expanded={expanded}
              onToggleFile={toggleFile}
              onToggleDir={toggleDir}
              onToggleExpand={toggleExpand}
            />
          )}
        </div>

        {/* Aperçu live du document assemblé */}
        <PreviewPanel
          paths={selectedPaths}
          format={format}
          disabled={selectedFiles.length === 0 || overSizeLimit}
          maxBytes={config.maxBytes}
        />

        {/* Actions finales */}
        <div className="flex flex-wrap items-center gap-2 rounded-xl border border-border bg-card p-3">
          <div className="inline-flex items-center gap-2 text-xs text-muted-foreground">
            <FolderTree className="h-3.5 w-3.5 text-primary" aria-hidden />
            <span>
              {selectedFiles.length} fichier(s) · format {format.toUpperCase()}
            </span>
          </div>

          <div className="ml-auto flex flex-wrap items-center gap-2">
            {/* Toggle format MD / JSON */}
            <div
              role="group"
              aria-label="Format du document"
              className="inline-flex rounded-lg border border-border bg-background p-0.5"
            >
              <button
                type="button"
                onClick={() => setFormat("md")}
                aria-pressed={format === "md"}
                className={`inline-flex items-center gap-1 rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
                  format === "md"
                    ? "bg-primary text-primary-foreground"
                    : "text-muted-foreground hover:bg-muted hover:text-foreground"
                }`}
              >
                <FileText className="h-3.5 w-3.5" aria-hidden />
                MD
              </button>
              <button
                type="button"
                onClick={() => setFormat("json")}
                aria-pressed={format === "json"}
                className={`inline-flex items-center gap-1 rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
                  format === "json"
                    ? "bg-primary text-primary-foreground"
                    : "text-muted-foreground hover:bg-muted hover:text-foreground"
                }`}
              >
                <FileJson className="h-3.5 w-3.5" aria-hidden />
                JSON
              </button>
            </div>

            {/* Nom de fichier : basename + extension calculée */}
            <div className="inline-flex items-center gap-1.5 rounded-lg border border-border bg-background px-2 py-1">
              <input
                type="text"
                value={basename}
                onChange={(e) => setBasename(e.target.value)}
                spellCheck={false}
                aria-label="Nom du fichier de sauvegarde (sans extension)"
                className="w-40 bg-transparent font-mono text-xs text-foreground outline-none"
              />
              <span className="font-mono text-xs text-muted-foreground">
                .{format}
              </span>
              <button
                type="button"
                onClick={handleSave}
                disabled={saving || selectedFiles.length === 0 || overSizeLimit}
                className="inline-flex items-center gap-1.5 rounded-md bg-chart-4/10 px-2.5 py-1 text-xs font-medium text-chart-4 transition-colors hover:bg-chart-4/20 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {saving ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden />
                ) : (
                  <Save className="h-3.5 w-3.5" aria-hidden />
                )}
                Sauvegarder
              </button>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}

app/back-studio/saveApp/TreeView.tsx:
/*
path :           app/back-studio/saveApp/TreeView.tsx
projectId:       <à fournir>
type:            component
generic:         false

role:            Arborescence récursive avec cases à cocher tri-état pour les dossiers
                 (coché / partiel / vide). Affiche le type et les tags de chaque fichier
                 sous forme de badges. Utilisée par SaveAppView.
flow:            Reçoit nodes (TreeNode[]), selected (Set<string>), expanded (Set<string>)
                 et des callbacks. Le parent contrôle l'état : le composant est purement
                 contrôlé. Récursion sur TreeDir.
ecosystem:       Dev = [
                   "@/app/back-studio/saveApp/page.tsx",
                   "@/app/back-studio/saveApp/SaveAppView.tsx",
                   "@/app/back-studio/saveApp/TreeView.tsx",
                   "@/lib/dev/types.ts",
                   "@/lib/dev/buildTree.ts",
                 ]
relatedFiles:    ["@/lib/dev/types.ts",
                  "@/app/back-studio/saveApp/SaveAppView.tsx"]
imports:         ["react", "lucide-react",
                  "@/lib/dev/types",
                  "props reçues : { nodes: readonly TreeNode[]; selected: Set<string>; expanded: Set<string>; onToggleFile: (path: string) => void; onToggleDir: (dir: TreeDir) => void; onToggleExpand: (path: string) => void; }"]
exports:         ["TreeView", "TreeViewProps"]
useBy:           ["@/app/back-studio/saveApp/SaveAppView.tsx"]

userStories:     ["*en tant que développeur je veux sélectionner des fichiers dans une arborescence"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

"use client";
// "use client" justifié : interactions utilisateur (clic, toggle).

import {
  ChevronDown,
  ChevronRight,
  Folder,
  FolderOpen,
  FileText,
} from "lucide-react";

import type { AppFile, TreeDir, TreeFile, TreeNode } from "@/lib/dev/types";

export type TreeViewProps = {
  readonly nodes: readonly TreeNode[];
  readonly selected: Set<string>;
  readonly expanded: Set<string>;
  readonly onToggleFile: (path: string) => void;
  readonly onToggleDir: (dir: TreeDir) => void;
  readonly onToggleExpand: (path: string) => void;
};

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function collectFiles(node: TreeNode): AppFile[] {
  if (node.kind === "file") return [node.file];
  const out: AppFile[] = [];
  for (const child of node.children) out.push(...collectFiles(child));
  return out;
}

function dirState(
  dir: TreeDir,
  selected: Set<string>,
): "all" | "none" | "partial" {
  const files = collectFiles(dir);
  if (files.length === 0) return "none";
  let sel = 0;
  for (const f of files) if (selected.has(f.relativePath)) sel++;
  if (sel === 0) return "none";
  if (sel === files.length) return "all";
  return "partial";
}

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function TreeView({
  nodes,
  selected,
  expanded,
  onToggleFile,
  onToggleDir,
  onToggleExpand,
}: TreeViewProps) {
  return (
    <ul className="flex flex-col gap-0.5">
      {nodes.map((node) => (
        <li key={node.kind === "dir" ? `d:${node.path}` : `f:${node.path}`}>
          {node.kind === "dir" ? (
            <DirRow
              dir={node}
              selected={selected}
              expanded={expanded}
              onToggleDir={onToggleDir}
              onToggleExpand={onToggleExpand}
              onToggleFile={onToggleFile}
            />
          ) : (
            <FileRow file={node} selected={selected} onToggle={onToggleFile} />
          )}
        </li>
      ))}
    </ul>
  );
}

/* ------------------------------------------------------------------ */
/*  Ligne dossier                                                      */
/* ------------------------------------------------------------------ */

function DirRow({
  dir,
  selected,
  expanded,
  onToggleDir,
  onToggleExpand,
  onToggleFile,
}: {
  dir: TreeDir;
  selected: Set<string>;
  expanded: Set<string>;
  onToggleDir: (dir: TreeDir) => void;
  onToggleExpand: (path: string) => void;
  onToggleFile: (path: string) => void;
}) {
  const state = dirState(dir, selected);
  const isOpen = expanded.has(dir.path);

  return (
    <div className="flex flex-col">
      <div className="flex items-center gap-1 rounded-md px-2 py-1 hover:bg-muted/40">
        <button
          type="button"
          onClick={() => onToggleExpand(dir.path)}
          aria-label={isOpen ? "Replier" : "Déplier"}
          className="grid size-5 shrink-0 place-items-center rounded text-muted-foreground hover:text-foreground"
        >
          {isOpen ? (
            <ChevronDown className="h-3.5 w-3.5" aria-hidden />
          ) : (
            <ChevronRight className="h-3.5 w-3.5" aria-hidden />
          )}
        </button>

        <input
          type="checkbox"
          checked={state === "all"}
          ref={(el) => {
            if (el) el.indeterminate = state === "partial";
          }}
          onChange={() => onToggleDir(dir)}
          className="h-3.5 w-3.5 shrink-0 accent-primary"
        />

        {isOpen ? (
          <FolderOpen
            className="h-4 w-4 shrink-0 text-primary/70"
            aria-hidden
          />
        ) : (
          <Folder className="h-4 w-4 shrink-0 text-primary/70" aria-hidden />
        )}

        <span className="font-mono text-xs font-semibold text-foreground">
          {dir.name}
        </span>
      </div>

      {isOpen && (
        <div className="ml-5 border-l border-border/60 pl-2">
          <TreeView
            nodes={dir.children}
            selected={selected}
            expanded={expanded}
            onToggleFile={onToggleFile}
            onToggleDir={onToggleDir}
            onToggleExpand={onToggleExpand}
          />
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Ligne fichier                                                      */
/* ------------------------------------------------------------------ */

function FileRow({
  file,
  selected,
  onToggle,
}: {
  file: TreeFile;
  selected: Set<string>;
  onToggle: (path: string) => void;
}) {
  const isSelected = selected.has(file.path);
  const header = file.file.header;

  return (
    <label className="flex cursor-pointer items-center gap-2 rounded-md px-2 py-1 hover:bg-muted/40">
      <span className="w-5 shrink-0" aria-hidden />

      <input
        type="checkbox"
        checked={isSelected}
        onChange={() => onToggle(file.path)}
        className="h-3.5 w-3.5 shrink-0 accent-primary"
      />

      <FileText
        className="h-3.5 w-3.5 shrink-0 text-muted-foreground"
        aria-hidden
      />

      <span className="min-w-0 flex-1 truncate font-mono text-xs text-foreground">
        {file.name}
      </span>

      {header.type && (
        <span className="shrink-0 rounded-full border border-border/60 bg-muted/40 px-1.5 py-0.5 font-mono text-[9px] text-muted-foreground">
          {header.type}
        </span>
      )}

      {header.tag.length > 0 &&
        header.tag.slice(0, 2).map((t) => (
          <span
            key={t}
            className="shrink-0 rounded-full border border-chart-1/30 bg-chart-1/10 px-1.5 py-0.5 font-mono text-[9px] text-chart-1"
          >
            {t}
          </span>
        ))}

      {header.tag.length > 2 && (
        <span className="shrink-0 font-mono text-[9px] text-muted-foreground">
          +{header.tag.length - 2}
        </span>
      )}
    </label>
  );
}

