scriptChecked:   ✘false
*/

"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  type ReactElement,
} from "react";
import { Check, Copy, Loader2, Sparkles } from "lucide-react";
import { toast } from "sonner";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export type ExportJsonDialogProps = {
  readonly trigger: ReactElement;
  readonly title: string;
  readonly description?: string;

  /** Payload léger (toujours affiché en premier). */
  readonly data: unknown;

  /**
   * Optionnel : Server Action qui retourne le payload complet (avec
   * dépendances). Si fournie, un toggle apparaît dans le dialog.
   */
  readonly fullFetcher?: () => Promise<unknown>;

  /** Libellé du toggle quand `fullFetcher` est fourni. */
  readonly fullToggleLabel?: string;

  readonly emptyMessage?: string;
  readonly rows?: number;
};

type Mode = "light" | "full";

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function ExportJsonDialog({
  trigger,
  title,
  description,
  data,
  fullFetcher,
  fullToggleLabel = "Inclure les dépendances",
  emptyMessage = "Aucune donnée à exporter.",
  rows = 20,
}: ExportJsonDialogProps) {
  const [open, setOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const [mode, setMode] = useState<Mode>("light");

  /* Résultat du fetch complet (lazy). */
  const [fullData, setFullData] = useState<unknown>(null);
  const [loadingFull, setLoadingFull] = useState(false);

  /* Reset à la fermeture : on repart en mode léger. */
  useEffect(() => {
    if (!open) {
      setMode("light");
      setFullData(null);
      setLoadingFull(false);
    }
  }, [open]);

  /* Charge les données complètes la première fois qu'on bascule. */
  useEffect(() => {
    if (mode !== "full" || !fullFetcher) return;
    if (fullData !== null || loadingFull) return;

    let cancelled = false;
    setLoadingFull(true);

    fullFetcher()
      .then((result) => {
        if (cancelled) return;
        setFullData(result);
      })
      .catch((err) => {
        if (cancelled) return;
        toast.error(
          err instanceof Error ? err.message : "Chargement impossible.",
        );
        setMode("light");
      })
      .finally(() => {
        if (cancelled) return;
        setLoadingFull(false);
      });

    return () => {
      cancelled = true;
    };
  }, [mode, fullFetcher, fullData, loadingFull]);

  /* Contenu à afficher selon le mode. */
  const json = useMemo(() => {
    const source = mode === "full" ? fullData : data;
    if (source === null || source === undefined) return "";
    if (Array.isArray(source) && source.length === 0) return "";
    return JSON.stringify(source, null, 2);
  }, [mode, fullData, data]);

  const isEmpty = json.length === 0;
  const showLoading = mode === "full" && loadingFull;

  /* ---------- Copie ---------- */

  const handleCopy = useCallback(async () => {
    if (isEmpty) {
      toast.error("Rien à copier.");
      return;
    }
    try {
      await navigator.clipboard.writeText(json);
      setCopied(true);
      toast.success("JSON copié dans le presse-papiers.");
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error("Copie impossible.");
    }
  }, [json, isEmpty]);

  /* ---------- Toggle ---------- */

  function toggleMode() {
    if (!fullFetcher) return;
    setMode((m) => (m === "light" ? "full" : "light"));
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger render={trigger} />

      <DialogContent className="flex max-h-[85vh] flex-col gap-4 sm:max-w-2xl">
        <DialogHeader className="shrink-0">
          <DialogTitle>{title}</DialogTitle>
          {description && <DialogDescription>{description}</DialogDescription>}
        </DialogHeader>

        {/* Toggle "Inclure les dépendances" (si fullFetcher fourni) */}
        {fullFetcher && (
          <button
            type="button"
            onClick={toggleMode}
            disabled={loadingFull}
            aria-pressed={mode === "full"}
            className={[
              "inline-flex w-fit items-center gap-2 rounded-full border px-3 py-1.5 text-xs font-medium transition-colors",
              mode === "full"
                ? "border-violet-500/40 bg-violet-500/10 text-violet-700 dark:text-violet-300"
                : "border-border bg-background text-muted-foreground hover:bg-muted",
              loadingFull && "cursor-wait opacity-60",
            ]
              .filter(Boolean)
              .join(" ")}
          >
            {loadingFull ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden />
            ) : (
              <Sparkles className="h-3.5 w-3.5" aria-hidden />
            )}
            {mode === "full" ? "Dépendances incluses" : fullToggleLabel}
          </button>
        )}

        {/* Contenu JSON */}
        <div className="min-h-0 flex-1 overflow-y-auto">
          {showLoading ? (
            <div className="flex items-center justify-center rounded-md border border-dashed bg-muted/20 p-12">
              <div className="flex flex-col items-center gap-2">
                <Loader2
                  className="h-5 w-5 animate-spin text-muted-foreground"
                  aria-hidden
                />
                <p className="text-xs italic text-muted-foreground">
                  Chargement des dépendances…
                </p>
              </div>
            </div>
          ) : isEmpty ? (
            <div className="flex items-center justify-center rounded-md border border-dashed bg-muted/20 p-8">
              <p className="text-xs italic text-muted-foreground">
                {emptyMessage}
              </p>
            </div>
          ) : (
            <Textarea
              value={json}
              readOnly
              rows={rows}
              spellCheck={false}
              className="font-mono text-xs leading-relaxed"
            />
          )}
        </div>

        {/* Pied */}
        <div className="flex shrink-0 items-center justify-between gap-2 border-t pt-4">
          <span className="font-mono text-[10px] text-muted-foreground">
            {json.length.toLocaleString()} caractères
          </span>
          <Button
            type="button"
            onClick={handleCopy}
            disabled={isEmpty || showLoading}
            className="gap-2"
          >
            {copied ? (
              <>
                <Check className="h-4 w-4 text-emerald-500" aria-hidden />
                Copié
              </>
            ) : (
              <>
                <Copy className="h-4 w-4" aria-hidden />
                Copier le JSON
              </>
            )}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

