"use client";

import { useState, useTransition, type ReactElement } from "react";
import {
  Check,
  ClipboardPaste,
  Copy,
  Loader2,
  Plus,
  RotateCcw,
} from "lucide-react";
import { toast } from "sonner";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import type { BulkImportResult } from "@/lib/actions/types";

export type ImportJsonDialogProps = {
  readonly trigger: ReactElement;
  readonly title: string;
  readonly description: string;
  readonly template: string;
  readonly submitLabel?: string;
  readonly onSubmit: (rawJson: string) => Promise<BulkImportResult>;
  readonly onSuccess?: () => void;
};

export function ImportJsonDialog({
  trigger,
  title,
  description,
  template,
  submitLabel = "Importer",
  onSubmit,
  onSuccess,
}: ImportJsonDialogProps) {
  const [open, setOpen] = useState(false);
  const [text, setText] = useState(template);
  const [copied, setCopied] = useState(false);
  const [isPending, startTransition] = useTransition();

  async function handleCopyTemplate() {
    try {
      await navigator.clipboard.writeText(template);
      setCopied(true);
      toast.success("Template copié dans le presse-papiers.");
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error("Copie impossible.");
    }
  }

  function handleReset() {
    setText(template);
  }

  function handleSubmit() {
    startTransition(async () => {
      const result = await onSubmit(text);

      if (result.success) {
        toast.success(
          `${result.imported} élément${result.imported > 1 ? "s" : ""} ajouté${
            result.imported > 1 ? "s" : ""
          }.`,
        );
        setText(template);
        setOpen(false);
        onSuccess?.();
      } else {
        toast.error(result.error);
      }
    });
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger render={trigger} />

      <DialogContent className="flex max-h-[85vh] flex-col gap-4 sm:max-w-2xl">
        <DialogHeader className="shrink-0">
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>

        {/* Barre d'outils template */}
        <div className="flex flex-wrap items-center justify-between gap-2">
          <span className="text-xs text-muted-foreground">
            Template JSON prêt à l&apos;emploi
          </span>
          <div className="flex items-center gap-1.5">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleCopyTemplate}
              className="h-7 gap-1.5 px-2 text-[11px]"
            >
              {copied ? (
                <>
                  <Check className="h-3 w-3 text-emerald-500" aria-hidden />
                  Copié
                </>
              ) : (
                <>
                  <Copy className="h-3 w-3" aria-hidden />
                  Copier le template
                </>
              )}
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleReset}
              className="h-7 gap-1.5 px-2 text-[11px]"
            >
              <RotateCcw className="h-3 w-3" aria-hidden />
              Réinitialiser
            </Button>
          </div>
        </div>

        {/* Textarea éditable */}
        <div className="min-h-0 flex-1 overflow-y-auto">
          <Textarea
            value={text}
            onChange={(e) => setText(e.target.value)}
            rows={20}
            spellCheck={false}
            className="font-mono text-xs leading-relaxed"
          />
        </div>

        {/* Footer */}
        <DialogFooter className="shrink-0 border-t pt-4">
          <Button
            type="button"
            variant="outline"
            onClick={() => setOpen(false)}
            disabled={isPending}
          >
            Annuler
          </Button>
          <Button
            type="button"
            onClick={handleSubmit}
            disabled={isPending || text.trim().length === 0}
            className="gap-2"
          >
            {isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" aria-hidden />
            ) : (
              <Plus className="h-4 w-4" aria-hidden />
            )}
            {submitLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

