                  "@/lib/project/serialize-for-disk"]
exports:         ["serializeAllProjectsForDisk"]

userStories:     ["*en tant que développeur je veux exporter tous mes projets avec dépendances"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

import "server-only";

import { prisma } from "@/lib/prisma";
import type { ProjectDiskSnapshot } from "@/lib/project/serialize-for-disk";

/* ------------------------------------------------------------------ */
/*  Helper de groupage — accepte projectId nullable                    */
/* ------------------------------------------------------------------ */

function groupByProject<T extends { projectId: string | null }>(
  items: readonly T[],
): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const item of items) {
    // Persona peut avoir projectId null → on l'ignore silencieusement.
    if (item.projectId === null) continue;
    const list = map.get(item.projectId) ?? [];
    list.push(item);
    map.set(item.projectId, list);
  }
  return map;
}

/* ------------------------------------------------------------------ */
/*  Sérialisation bulk                                                 */
/* ------------------------------------------------------------------ */

export async function serializeAllProjectsForDisk(
  userId: string,
): Promise<ProjectDiskSnapshot[]> {
  /* ---------- 1. Projets ---------- */

  const projects = await prisma.project.findMany({
    where: { ownerId: userId, deletedAt: null },
    orderBy: [{ displayOrder: "asc" }, { createdAt: "desc" }],
    select: {
      id: true,
      name: true,
      slug: true,
      tagline: true,
      description: true,
      status: true,
    },
  });

  if (projects.length === 0) return [];

  const projectIds = projects.map((p) => p.id);

  /* ---------- 2. Enfants en 4 requêtes ---------- */

  const [features, personas, stories, sprints] = await Promise.all([
    prisma.feature.findMany({
      where: { projectId: { in: projectIds } },
      orderBy: [{ displayOrder: "asc" }, { name: "asc" }],
      select: {
        id: true,
        projectId: true,
        name: true,
        slug: true,
        description: true,
        module: true,
        icon: true,
        accent: true,
        displayOrder: true,
      },
    }),

    prisma.persona.findMany({
      where: { projectId: { in: projectIds }, deletedAt: null },
      orderBy: [{ displayOrder: "asc" }, { name: "asc" }],
      select: {
        id: true,
        projectId: true,
        name: true,
        slug: true,
        value: true,
        keywords: true,
        icon: true,
        accent: true,
        displayOrder: true,
      },
    }),

    prisma.userStory.findMany({
      where: { projectId: { in: projectIds }, deletedAt: null },
      orderBy: [{ displayOrder: "asc" }, { createdAt: "asc" }],
      select: {
        id: true,
        projectId: true,
        parentId: true,
        slug: true,
        title: true,
        personaRef: true,
        asA: true,
        iWant: true,
        soThat: true,
        status: true,
        priority: true,
        storyPoints: true,
        accent: true,
        sprintId: true,
        acceptanceCriteria: true,
        dodChecked: true,
        linkedFiles: true,
        displayOrder: true,
      },
    }),

    prisma.sprint.findMany({
      where: { projectId: { in: projectIds }, deletedAt: null },
      orderBy: [{ displayOrder: "asc" }, { startDate: "asc" }],
      select: {
        id: true,
        projectId: true,
        name: true,
        slug: true,
        goal: true,
        startDate: true,
        endDate: true,
        durationWeeks: true,
        status: true,
        capacityPoints: true,
        velocity: true,
        notes: true,
        accent: true,
        displayOrder: true,
      },
    }),
  ]);

  /* ---------- 3. Groupage par projet ---------- */

  const featuresByProject = groupByProject(features);
  const personasByProject = groupByProject(personas);
  const storiesByProject = groupByProject(stories);
  const sprintsByProject = groupByProject(sprints);

  /* ---------- 4. Construction des snapshots ---------- */

  return projects.map((project) => {
    const pFeatures = featuresByProject.get(project.id) ?? [];
    const pPersonas = personasByProject.get(project.id) ?? [];
    const pStories = storiesByProject.get(project.id) ?? [];
    const pSprints = sprintsByProject.get(project.id) ?? [];

    /* Maps id → slug pour convertir parentId et sprintId. */
    const storySlugById = new Map(pStories.map((s) => [s.id, s.slug]));
    const sprintSlugById = new Map(pSprints.map((s) => [s.id, s.slug]));

    return {
      project: {
        name: project.name,
        slug: project.slug,
        tagline: project.tagline,
        description: project.description,
        status: project.status,
      },

      features: pFeatures.map((f) => ({
        name: f.name,
        slug: f.slug,
        description: f.description,
        module: f.module,
        icon: f.icon,
        accent: f.accent,
        displayOrder: f.displayOrder,
      })),

      personas: pPersonas.map((p) => ({
        name: p.name,
        slug: p.slug,
        value: p.value,
        keywords: p.keywords,
        icon: p.icon,
        accent: p.accent,
        displayOrder: p.displayOrder,
      })),

      userStories: pStories.map((s) => ({
        parentSlug: s.parentId
          ? (storySlugById.get(s.parentId) ?? null)
          : null,
        slug: s.slug,
        title: s.title,
        personaRef: s.personaRef,
        asA: s.asA,
        iWant: s.iWant,
        soThat: s.soThat,
        status: s.status,
        priority: s.priority,
        storyPoints: s.storyPoints,
        accent: s.accent,
        sprintSlug: s.sprintId
          ? (sprintSlugById.get(s.sprintId) ?? null)
          : null,
        acceptanceCriteria: s.acceptanceCriteria,
        dodChecked: s.dodChecked,
        linkedFiles: s.linkedFiles,
        displayOrder: s.displayOrder,
      })),

      sprints: pSprints.map((s) => ({
        name: s.name,
        slug: s.slug,
        goal: s.goal,
        startDate: s.startDate.toISOString().slice(0, 10),
        endDate: s.endDate.toISOString().slice(0, 10),
        durationWeeks: s.durationWeeks,
        status: s.status,
        capacityPoints: s.capacityPoints,
        velocity: s.velocity,
        notes: s.notes,
        accent: s.accent,
        displayOrder: s.displayOrder,
      })),
    } satisfies ProjectDiskSnapshot;
  });
}

