/*
path :           lib/prompts/read-contributing.ts
tag :            ["prompt", "contributing"]
projectId:       <à fournir>
type:            helper
generic:         true

role:            Lecture serveur de CONTRIBUTING.md à la racine du projet.
                 Retourne le contenu du fichier s'il existe, sinon le
                 contenu par défaut. Ne lève jamais.

flow:            readContributing() → fs.readFile(CONTRIBUTING.md) →
                 si ENOENT : retourne DEFAULT_CONTRIBUTING_CONTENT
                 → sinon : retourne le contenu lu.

ecosystem:       Prompts = [
                   "@/lib/prompts/default-content.ts",
                   "@/lib/prompts/read-contributing.ts",
                 ]
relatedFiles:    ["@/lib/prompts/default-content.ts",
                  "@/app/back-studio/help-dev/prompt/page.tsx"]
imports:         ["server-only", "node:fs/promises", "node:path",
                  "@/lib/prompts/default-content"]
exports:         ["readContributing", "CONTRIBUTING_PATH"]
useBy:           ["@/app/back-studio/help-dev/prompt/page.tsx"]

userStories:     ["*en tant que développeur je veux lire le CONTRIBUTING actuel"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

import "server-only";

import { promises as fs } from "node:fs";
import path from "node:path";

import { DEFAULT_CONTRIBUTING_CONTENT } from "@/lib/prompts/default-content";

export const CONTRIBUTING_PATH = path.join(process.cwd(), "CONTRIBUTING.md");

export async function readContributing(): Promise<string> {
  try {
    return await fs.readFile(CONTRIBUTING_PATH, "utf-8");
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOENT") {
      return DEFAULT_CONTRIBUTING_CONTENT;
    }
    console.error("[readContributing]", err);
    return DEFAULT_CONTRIBUTING_CONTENT;
  }
}

lib/user-story/json.ts:
/*
path :           lib/user-story/json.ts
projectId:       <à fournir>
type:            helper
generic:         true

role:            Sérialisation/désérialisation des 3 champs JSON du modèle UserStory :
                 acceptanceCriteria (AcceptanceCriterion[]), dodChecked (string[]),
                 linkedFiles (string[]). Tolérant aux données invalides (retourne []
                 au lieu de lever).
flow:            parseAcceptanceCriteria(raw) → AcceptanceCriterion[].
                 stringifyAcceptanceCriteria(list) → string | null.
                 parseStringList(raw) → string[].
                 stringifyStringList(list) → string | null.
ecosystem:       Dev = [
                   "@/lib/user-story/json.ts",
                   "@/app/actions/user-story/createUserStory.ts",
                 ]
relatedFiles:    ["@/lib/validations/user-story.ts",
                  "@/components/user-story/UserStoryForm.tsx"]
imports:         []
exports:         ["AcceptanceCriterion",
                  "parseAcceptanceCriteria", "stringifyAcceptanceCriteria",
                  "parseStringList", "stringifyStringList"]

userStories:     ["*en tant que développeur je veux sérialiser les champs JSON d'une user story"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export type AcceptanceCriterion = {
  readonly id: string;
  readonly text: string;
  readonly done: boolean;
};

/* ------------------------------------------------------------------ */
/*  Acceptance criteria                                                */
/* ------------------------------------------------------------------ */

function isAcceptanceCriterion(v: unknown): v is AcceptanceCriterion {
  if (!v || typeof v !== "object") return false;
  const o = v as Record<string, unknown>;
  return (
    typeof o.id === "string" &&
    typeof o.text === "string" &&
    typeof o.done === "boolean"
  );
}

export function parseAcceptanceCriteria(raw: string | null): AcceptanceCriterion[] {
  if (!raw) return [];
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isAcceptanceCriterion);
  } catch {
    return [];
  }
}

export function stringifyAcceptanceCriteria(
  list: readonly AcceptanceCriterion[],
): string | null {
  if (list.length === 0) return null;
  return JSON.stringify(list);
}

/* ------------------------------------------------------------------ */
/*  Listes de chaînes (dodChecked, linkedFiles)                        */
/* ------------------------------------------------------------------ */

export function parseStringList(raw: string | null): string[] {
  if (!raw) return [];
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((v): v is string => typeof v === "string");
  } catch {
    return [];
  }
}

export function stringifyStringList(list: readonly string[]): string | null {
  const cleaned = list.map((s) => s.trim()).filter((s) => s.length > 0);
  if (cleaned.length === 0) return null;
  return JSON.stringify(cleaned);
}

lib/validations/auth.ts:
// src/lib/validations/auth.ts
/*
  role:           Schémas Zod pour l'authentification : inscription,
                  connexion, mot de passe oublié, réinitialisation,
                  changement de mot de passe. Source unique de vérité
                  pour la validation des entrées.

  flow:           Importé par les formulaires (react-hook-form) et
                  réutilisable côté serveur. Les schémas sont utilisés
                  via zodResolver dans chaque formulaire.

  imports:        zod.

  structure:      - interface PasswordRule + PASSWORD_RULES
                  - interface PasswordStrength + getPasswordStrength
                  - imageField (URL http(s) OU data URL base64)
                  - registerSchema + RegisterInput
                  - loginSchema + LoginInput
                  - forgotPasswordSchema + ForgotPasswordInput
                  - resetPasswordSchema + ResetPasswordInput
                  - changePasswordSchema + ChangePasswordInput

  ecosysteme:     Auth

  usedBy:         LoginForm, RegisterForm, ForgotPasswordForm,
                  ResetPasswordForm, PasswordForm.

  notes:          - imageField accepte deux formats :
                    · URL http(s) — ex. https://exemple.com/avatar.jpg
                    · data URL base64 — ex. data:image/png;base64,iVBOR…
                  - Un champ vide est transformé en undefined pour que
                    BetterAuth reçoive null côté base de données.
                  - Les schémas réutilisent les mêmes règles pour
                    register et resetPassword (confirmation du mot de
                    passe).
*/

import { z } from "zod";

/* ------------------------------------------------------------------ */
/*  Règles de mot de passe                                             */
/* ------------------------------------------------------------------ */

export interface PasswordRule {
  readonly id: string;
  readonly label: string;
  readonly test: (value: string) => boolean;
}

export const PASSWORD_RULES: readonly PasswordRule[] = [
  {
    id: "length",
    label: "8 caractères minimum",
    test: (v) => v.length >= 8,
  },
  {
    id: "lower",
    label: "Une minuscule",
    test: (v) => /[a-z]/.test(v),
  },
  {
    id: "upper",
    label: "Une majuscule",
    test: (v) => /[A-Z]/.test(v),
  },
  {
    id: "digit",
    label: "Un chiffre",
    test: (v) => /\d/.test(v),
  },
  {
    id: "special",
    label: "Un caractère spécial",
    test: (v) => /[^A-Za-z0-9]/.test(v),
  },
] as const;

/* ------------------------------------------------------------------ */
/*  Force du mot de passe                                              */
/* ------------------------------------------------------------------ */

export interface PasswordStrength {
  readonly score: 0 | 1 | 2 | 3 | 4;
  readonly label: string;
}

const STRENGTH_LABELS: Record<0 | 1 | 2 | 3 | 4, string> = {
  0: "—",
  1: "Faible",
  2: "Moyen",
  3: "Bon",
  4: "Fort",
};

export function getPasswordStrength(value: string): PasswordStrength {
  if (!value) {
    return { score: 0, label: STRENGTH_LABELS[0] };
  }

  const passed = PASSWORD_RULES.filter((rule) => rule.test(value)).length;

  let score: 0 | 1 | 2 | 3 | 4;
  if (passed <= 1) score = 1;
  else if (passed === 2) score = 2;
  else if (passed === 3) score = 2;
  else if (passed === 4) score = 3;
  else score = 4;

  return { score, label: STRENGTH_LABELS[score] };
}

/* ------------------------------------------------------------------ */
/*  Champ image (URL http(s) OU data URL base64)                       */
/* ------------------------------------------------------------------ */

const imageField = z
  .string()
  .trim()
  .transform((v) => (v === "" ? undefined : v))
  .optional()
  .refine(
    (v) =>
      v === undefined ||
      /^https?:\/\/.+/.test(v) ||
      /^data:image\/[a-z0-9.+-]+;base64,/i.test(v),
    {
      message:
        "Format d'image invalide (URL http(s) ou data URL base64 attendu).",
    },
  );

/* ------------------------------------------------------------------ */
/*  Inscription                                                        */
/* ------------------------------------------------------------------ */

export const registerSchema = z
  .object({
    name: z
      .string()
      .trim()
      .min(2, { message: "Nom : 2 caractères minimum." })
      .max(60, { message: "Nom : 60 caractères maximum." }),

    email: z
      .email({ message: "Adresse email invalide." })
      .transform((v) => v.toLowerCase().trim()),

    password: z
      .string()
      .min(8, { message: "Mot de passe : 8 caractères minimum." })
      .max(128, { message: "Mot de passe : 128 caractères maximum." }),

    confirmPassword: z
      .string()
      .min(1, { message: "Confirmez le mot de passe." }),

    image: imageField,
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "Les mots de passe ne correspondent pas.",
    path: ["confirmPassword"],
  });

export type RegisterInput = z.infer<typeof registerSchema>;

/* ------------------------------------------------------------------ */
/*  Connexion                                                          */
/* ------------------------------------------------------------------ */

export const loginSchema = z.object({
  email: z
    .email({ message: "Adresse email invalide." })
    .transform((v) => v.toLowerCase().trim()),

  password: z
    .string()
    .min(1, { message: "Mot de passe requis." }),
});

export type LoginInput = z.infer<typeof loginSchema>;

/* ------------------------------------------------------------------ */
/*  Mot de passe oublié                                                */
/* ------------------------------------------------------------------ */

export const forgotPasswordSchema = z.object({
  email: z
    .email({ message: "Adresse email invalide." })
    .transform((v) => v.toLowerCase().trim()),
});

export type ForgotPasswordInput = z.infer<typeof forgotPasswordSchema>;

/* ------------------------------------------------------------------ */
/*  Réinitialisation du mot de passe                                   */
/* ------------------------------------------------------------------ */

export const resetPasswordSchema = z
  .object({
    token: z.string().min(1, { message: "Jeton manquant." }),
    password: z
      .string()
      .min(8, { message: "Mot de passe : 8 caractères minimum." })
      .max(128, { message: "Mot de passe : 128 caractères maximum." }),
    confirmPassword: z
      .string()
      .min(1, { message: "Confirmez le mot de passe." }),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "Les mots de passe ne correspondent pas.",
    path: ["confirmPassword"],
  });

export type ResetPasswordInput = z.infer<typeof resetPasswordSchema>;

/* ------------------------------------------------------------------ */
/*  Changement de mot de passe (utilisateur connecté)                  */
/* ------------------------------------------------------------------ */

export const changePasswordSchema = z
  .object({
    currentPassword: z
      .string()
      .min(1, { message: "Mot de passe actuel requis." }),
    newPassword: z
      .string()
      .min(8, { message: "Mot de passe : 8 caractères minimum." })
      .max(128, { message: "Mot de passe : 128 caractères maximum." }),
    confirmPassword: z
      .string()
      .min(1, { message: "Confirmez le mot de passe." }),
  })
  .refine((data) => data.newPassword === data.confirmPassword, {
    message: "Les mots de passe ne correspondent pas.",
    path: ["confirmPassword"],
  });

export type ChangePasswordInput = z.infer<typeof changePasswordSchema>;

lib/validations/creat-files.ts:
/*
path :           lib/validations/creat-files.ts
projectId:       <à fournir>
type:            helper
generic:         true

role:            Schémas Zod pour le payload de création de fichiers (CreatFiles). Valide
                 le tableau { path?, content }, borne les tailles (max 999 fichiers,
                 2 Mo par fichier), et le choix de politique en cas de conflit.
                 Le path est désormais OPTIONNEL : s'il est absent, la route /save le
                 déduit de l'en-tête Helpdev présent dans le contenu.
flow:            creatFilesPayloadSchema.safeParse(body) → { files, onConflict? }.
                 safePath est exporté pour que la route puisse valider les chemins
                 résolus après déduction.
ecosystem:       Dev = [
                   "@/app/api/back-studio/creat-files/save/route.ts",
                   "@/lib/validations/creat-files.ts",
                 ]
relatedFiles:    ["@/app/api/back-studio/creat-files/save/route.ts",
                  "@/app/back-studio/creatFiles/CreatFilesView.tsx"]
imports:         ["zod"]
exports:         ["creatFilesPayloadSchema", "CreatFilesPayload",
                  "ConflictPolicy", "conflictPolicySchema", "safePath"]

userStories:     ["*en tant que développeur je veux valider les fichiers à créer"]
status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

import { z } from "zod";

/* ------------------------------------------------------------------ */
/*  Détection de traversée basée sur les segments                      */
/* ------------------------------------------------------------------ */

function hasPathTraversal(s: string): boolean {
  if (s === "..") return true;
  if (s.startsWith("../")) return true;
  if (s.endsWith("/..")) return true;
  if (s.includes("/../")) return true;
  if (s.includes("//")) return true;
  return false;
}

/* ------------------------------------------------------------------ */
/*  Chemin relatif sûr (exporté pour la route)                         */
/* ------------------------------------------------------------------ */

export const safePath = z
  .string()
  .trim()
  .min(1, "Chemin vide.")
  .max(500, "Chemin trop long.")
  .refine((s) => !s.startsWith("/"), "Chemin absolu interdit.")
  .refine((s) => !s.startsWith("\\"), "UNC interdit.")
  .refine((s) => !hasPathTraversal(s), "Traversée « .. » interdite.")
  .refine((s) => !s.includes("\\"), "Séparateur Windows interdit.")
  .refine(
    (s) => !/[<>:"|?*\x00-\x1f]/.test(s),
    "Caractères interdits dans le chemin.",
  );

/* ------------------------------------------------------------------ */
/*  Politique de conflit                                               */
/* ------------------------------------------------------------------ */

export const conflictPolicySchema = z.enum(["skip", "overwrite", "rename"]);
export type ConflictPolicy = z.infer<typeof conflictPolicySchema>;

/* ------------------------------------------------------------------ */
/*  Payload                                                            */
/* ------------------------------------------------------------------ */

/**
 * `path` est optionnel côté validation Zod : la route /save le résout
 * ensuite depuis l'en-tête Helpdev du contenu. Une chaîne vide est
 * acceptée (traitée comme absence).
 */
export const creatFilesPayloadSchema = z.object({
  files: z
    .array(
      z.object({
        path: z.string().max(500, "Chemin trop long.").optional(),
        content: z
          .string()
          .max(2_000_000, "Contenu trop volumineux (2 Mo max par fichier)."),
      }),
    )
    .min(1, "Aucun fichier.")
    .max(999, "999 fichiers maximum."),
  onConflict: conflictPolicySchema.optional(),
});

export type CreatFilesPayload = z.infer<typeof creatFilesPayloadSchema>;

lib/validations/feature.ts:
/*
path :           lib/validations/feature.ts
projectId:       <à fournir>
